#!/bin/zsh
# usage: gpt-frames.sh   (edit jobs below) generates gpt-image-2 frames at 3:2, crops to 16:9
cd "$(dirname "$0")/../frames"; R=../ref
gen() { out=$1; shift; egaki image "$@" -m gpt-image-2 --aspect-ratio 3:2 --quality high -o gpt/$out.png >gpt/$out.log 2>&1 && ffmpeg -v error -y -i gpt/$out.png -vf "crop=iw:iw*9/16" gpt/$out-16x9.png && echo ok $out || echo FAIL $out; }
gen desk-hero "Photorealistic premium product hero shot. Red brick wall, walnut desk, a large display in the center showing a dark terminal app, a Mac mini, a keyboard and trackpad, and six iPhones in deep blue titanium on matte black aluminium stands (three each side) with neat white USB-C cables. Warm key light from the left, cool rim light, shallow depth of field, cinematic 35mm, tasteful and minimal. No floating icons, no logos, no text overlays. Wide composition." &
gen desk-hero-edit "Edit this photo into a premium cinematic version: same layout (brick wall, desk, large display, Mac mini, keyboard, six iPhones on stands), but matte black machined stands, tidy white cables, deep blue titanium iPhones, walnut desktop, warm key light and cool rim light, shallow depth of field. Remove all floating app icons and logos. Photorealistic." -i $R/orig-1.png &
gen three-phones "Photorealistic cinematic shot of three iPhones in deep blue titanium on matte black stands with thin warm ring-light bases, dark moody studio, red brick wall, warm amber string-light bokeh, glossy walnut table with reflections. Screens: left a TikTok-style cooking video feed, middle an Instagram-style photo feed, right a messaging chat. Crisp, premium, centered." &
gen three-phones-agents "Photorealistic three iPhones on stands in a row on a table, from the front, brick wall behind, dark studio, rim lights. Left screen: a maps route to an airport. Middle screen: a Reddit-style thread of restaurant recommendations. Right screen: a flight booking app seat-picking screen. Realistic UI, crisp." &
gen presenter-woman "Edit this photo: replace the man with a woman in her late 20s with short dark hair, charcoal crewneck sweater, no cap, speaking to camera with a friendly confident expression. Keep framing (medium close-up, centered), brick wall and large plant, upgrade the lighting to soft key plus hair light, shallow depth of field, natural skin. No logos or icons." -i $R/orig-20.png &
gen presenter-man "Edit this photo: replace the man with a different man in his 30s, short curly hair, clean-shaven, dark olive overshirt over a black t-shirt, no cap, speaking to camera. Keep framing, brick wall and plant, upgrade lighting to soft key plus rim light, shallow depth of field, natural skin. No logos or icons." -i $R/orig-20.png &
gen phone-closeup "Photorealistic close-up product photo of one deep blue titanium iPhone on a matte black stand with a ring-light base, white USB-C cable plugged in, screen showing a TikTok-style video feed, red brick wall softly blurred behind, walnut table, warm amber bokeh, 85mm shallow depth of field." &
gen terminal-mac "Photorealistic Mac Studio and Studio Display on a walnut desk in a dark studio. The display shows a dark terminal window with a coding agent session, white and green monospace text. Beside it a deep blue iPhone on a stand with a USB-C cable. Brick wall, rim light, shallow depth of field." &
gen phone-rack "Photorealistic wide shot of a neat phone farm: black metal rack with sixteen iPhones in a 4x4 grid, each on a small mount with a white cable, screens showing different apps, soft cool blue rim light and warm accent light, dark modern studio, symmetrical, cinematic." &
gen presenter-gesture "Photorealistic medium-wide shot: a woman in her late 20s with short dark hair and a charcoal sweater standing beside a walnut desk with three iPhones on matte black stands and a large dark display, brick wall and plant behind, soft cinematic light, she looks at camera and gestures toward the phones with an open hand. No text." &
gen hands-typing "Photorealistic close-up of hands typing on a white Apple Magic Keyboard on a walnut desk, shallow depth of field, a large display blurred behind showing a dark terminal, warm light, cinematic." &
gen studio-wide "Photorealistic wide establishing shot of a dark studio workspace: long walnut desk against a brick wall, six iPhones on matte black stands with white cables in a neat line, Mac Studio and big display in the middle, warm pendant lights, blue-hour window on the left, cinematic 35mm." &
